package com.fmrent.reservations.service;
import com.fasterxml.jackson.annotation.JsonProperty; import java.nio.charset.StandardCharsets; import java.util.Base64; import org.springframework.beans.factory.annotation.Value; import org.springframework.core.io.ByteArrayResource; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.util.*; import org.springframework.web.client.RestClient; import org.springframework.web.multipart.MultipartFile;
@Service public class PrivateDocumentService {private final RestClient client;public PrivateDocumentService(@Value("${imagekit.private-key}")String key){String basic=Base64.getEncoder().encodeToString((key+":").getBytes(StandardCharsets.UTF_8));client=RestClient.builder().defaultHeader(HttpHeaders.AUTHORIZATION,"Basic "+basic).build();}
 public String upload(MultipartFile file,String label){try{if(file.isEmpty()||file.getContentType()==null||!file.getContentType().startsWith("image/"))throw new IllegalArgumentException("Les justificatifs doivent être des images valides.");String name=label+"-"+System.currentTimeMillis()+".jpg";HttpHeaders headers=new HttpHeaders();headers.setContentType(MediaType.parseMediaType(file.getContentType()));ByteArrayResource resource=new ByteArrayResource(file.getBytes()){@Override public String getFilename(){return name;}};MultiValueMap<String,Object> body=new LinkedMultiValueMap<>();body.add("file",new HttpEntity<>(resource,headers));body.add("fileName",name);body.add("folder","/fm-rent/private/reservations");body.add("isPrivateFile","true");Upload result=client.post().uri("https://upload.imagekit.io/api/v1/files/upload").contentType(MediaType.MULTIPART_FORM_DATA).body(body).retrieve().body(Upload.class);if(result==null||result.fileId()==null)throw new IllegalStateException("Upload incomplet.");return result.fileId();}catch(IllegalArgumentException e){throw e;}catch(Exception e){throw new IllegalStateException("Échec de l'envoi sécurisé des justificatifs.",e);}}
 public void delete(String fileId){if(fileId==null||fileId.isBlank())return;client.delete().uri("https://api.imagekit.io/v1/files/{id}",fileId).retrieve().toBodilessEntity();}
 record Upload(@JsonProperty("fileId")String fileId){} }
